 "blockClientScript": "window.dispatch = (eventName, data, element) => {
  if (element && element === "string") {
    element = document.querySelector(element);
  } else if (!(element instanceof HTMLElement)) {
    element = document;
  }
  const event = new CustomEvent(eventName, { detail: data });
  element.dispatchEvent(event);
};
window.listen = (eventName, callback, element) => {
  if (element && element === "string") {
    element = document.querySelector(element);
  } else if (!(element instanceof HTMLElement)) {
    element = document;
  }
  element.addEventListener(eventName, callback);
};

window.frappe_call = async (type, method, body) => {
  try {
    dispatch("frappe-call-open");
    const res = await fetch(`/api/v2/method/${method}`, {
      method: type,
      headers: {
        "Content-Type": "application/json",
        "X-Frappe-CSRF-Token": frappe.csrf_token,
      },
      body: JSON.stringify(body),
    });

    // fetch won't throw for 4xx/5xx → you must do this manually
    if (!res.ok) {
      const errorText = await res.text(); // or res.json() if API returns JSON
      throw new Error(errorText || `HTTP error ${res.status}`);
    }

    dispatch("frappe-call-close");
    return await res.json();
  } catch (err) {
    dispatch("frappe-call-error");
    console.error("frappe_call error:", err);
    throw err; // rethrow so caller's try/catch works
  }
};",
